use vstd::prelude::*;

verus! {

/// Constructs a row of length `n` whose entries are 0,1,2,…,n-1.
fn create_row(n: u8) -> Vec<u8>
    ensures |res: &Vec<u8>|
        // the row has exactly n elements
        res.len() == n as nat
        // and for each valid index i, res[i] == i
        && forall|i: nat| i < res.len() ==> res[i] == (i as u8)
        // in particular the row is strictly increasing
        && forall|i,j: nat| i < j && j < res.len() ==> res[i] < res[j]
{
    let mut v: Vec<u8> = Vec::new();
    let mut i: u8 = 0;
    // build v by pushing 0,1,…,n-1
    while i < n
        invariant
            // we have pushed exactly i elements so far
            v.len() == i as nat,
            // and those elements satisfy v[j] == j for j < i
            forall|j: nat| j < v.len() ==> v[j] == (j as u8),
        decreases (n - i) as nat
    {
        v.push(i);
        i = i + 1;
    }
    v
}

/// Constructs a 2D grid with a single row,
/// where that row is exactly `create_row(n)`.
fn indices(n: u8) -> Vec<Vec<u8>>
    ensures |g: &Vec<Vec<u8>>|
        // exactly one row
        g.len() == 1
        // the row has length n and entries 0..n-1
        && g[0].len() == n as nat
        && forall|i: nat| i < g[0].len() ==> g[0][i] == (i as u8)
{
    let row = create_row(n);
    let mut grid: Vec<Vec<u8>> = Vec::new();
    grid.push(row);
    grid
}

}

fn main() {
    // Examples
    let r0 = create_row(0);
    assert(r0.len() == 0);
    let r5 = create_row(5);
    assert(r5 == vec![0,1,2,3,4]);

    let g3 = indices(3);
    assert(g3.len() == 1);
    assert(g3[0] == vec![0,1,2]);
}